# Helper: flatten nested dict into rows
def flatten_dict(d, model, condition):
    rows = []
    for country, topics in d.items():
        for topic, vals in topics.items():
            rows.append({
                "model": model,
                "condition": condition,
                "country": country,
                "topic": topic,
                "measure": vals["measure"],
                "agree_count": vals["agree_count"],
                "disagree_count": vals["disagree_count"],
                "total_rows": vals["total_rows"],
            })
    return rows

# Collect into DataFrame
all_rows = []
all_rows += flatten_dict(gpt_rolebased, "GPT", "Role-based")
all_rows += flatten_dict(gpt_native, "GPT", "Native")
all_rows += flatten_dict(gpt_assistant, "GPT", "Assistant")
all_rows += flatten_dict(llama_rolebased, "LLaMA", "Role-based")
all_rows += flatten_dict(llama_native, "LLaMA", "Native")
all_rows += flatten_dict(llama_assistant, "LLaMA", "Assistant")

df = pd.DataFrame(all_rows)

# --- Violin plot (grouped by model + condition) ---
plt.figure(figsize=(10,6))
sns.violinplot(
    data=df,
    x="model", y="measure",
    hue="condition",
    split=False,
    inner="quart",
    palette="Set2"
)

plt.ylabel("Agreement ratio")
plt.xlabel("Model")
plt.title("Distribution of Agreement Ratios by Model and Condition")
plt.ylim(0, 1)
plt.legend(title="Condition")
plt.tight_layout()

# Save in both PNG and PDF
plt.savefig("results/agreement_ratio_plots/agreement_violin.png", dpi=300)
plt.savefig("results/agreement_ratio_plots/agreement_violin.pdf")
plt.close()

print("Plots saved as agreement_violin.png and agreement_violin.pdf")